import { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import { getChildren } from "../api/api";

const allergyMap = {
  Blueberry: "Peanuts",
  "Rose Berry": "Milk",
  BlackBerry: "Soy",
  default: "No known allergies"
};

function ChildProfile() {
  const { id } = useParams();
  const [child, setChild] = useState(null);

  useEffect(() => {
    getChildren()
      .then(res => {
        const selected = res.find(c => String(c.id) === String(id));
        setChild(selected || null);
      })
      .catch(err => console.log(err));
  }, [id]);

  if (!child) {
    return (
      <div>
        <h2>Child Profile</h2>
        <p>Loading child details...</p>
        <Link to="/">Back to Home</Link>
      </div>
    );
  }

  const allergies = allergyMap[child.class] || allergyMap.default;

  return (
    <div style={{ maxWidth: "520px" }}>
      <h2>Child Profile</h2>
      <div style={{ display: "flex", gap: "16px", alignItems: "flex-start" }}>
        <img
          src={`https://via.placeholder.com/160?text=${encodeURIComponent(child.name)}`}
          alt={`${child.name} profile`}
          style={{ borderRadius: "16px", objectFit: "cover", width: "160px", height: "160px" }}
        />
        <div>
          <h3>{child.name}</h3>
          <p><strong>Age:</strong> {child.age}</p>
          <p><strong>Class:</strong> {child.class}</p>
          <p><strong>Allergies:</strong> {allergies}</p>
        </div>
      </div>
      <div style={{ marginTop: "18px" }}>
        <Link to="/">Back to Home</Link>
      </div>
    </div>
  );
}

export default ChildProfile;
